Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l3-video-cue",
  "level": "L3",
  "title": "Prototype becomes real",
  "purpose": "A 60 to 90 second cue for a short film sequence: failed prototype, quiet insight, successful test, unresolved final look.",
  "duration_seconds": 78,
  "section_plan": [
    "failure: 8 bars",
    "insight: 8 bars",
    "build: 8 bars",
    "success: 8 bars",
    "question: 4 bars"
  ],
  "style": [
    "hybrid chamber electronic",
    "motivic",
    "editor-friendly"
  ],
  "mood": [
    "frustrated",
    "curious",
    "uplifting",
    "slightly unresolved"
  ],
  "must_include": [
    "one motif survives all sections",
    "clear edit points",
    "success is earned rather than instantly maximal"
  ],
  "must_avoid": [
    "generic riser every transition",
    "full ensemble from bar one",
    "fully resolved final cadence"
  ],
  "instrument_roles": [
    "piano motif",
    "strings",
    "bass pulse",
    "electronic texture",
    "light percussion"
  ],
  "delivery": [
    "36 bars",
    "5 to 7 tracks",
    "section markers match picture beats"
  ],
  "score_focus": [
    "narrative arc",
    "transitions",
    "motif continuity"
  ],
  "mode_a": true
}

SKELETON:
{
  "title": "Prototype Becomes Real",
  "tempo_map": [
    {"bar": 1, "bpm": 100},
    {"bar": 17, "bpm": 120}
  ],
  "key_map": [
    {"bar": 1, "key": "D minor"},
    {"bar": 9, "key": "F major"},
    {"bar": 17, "key": "G major"},
    {"bar": 25, "key": "C major"},
    {"bar": 33, "key": "A minor"}
  ],
  "sections": [
    {"id": "failure", "name": "Failure", "start_bar": 1, "bars": 8},
    {"id": "insight", "name": "Insight", "start_bar": 9, "bars": 8},
    {"id": "build", "name": "Build", "start_bar": 17, "bars": 8},
    {"id": "success", "name": "Success", "start_bar": 25, "bars": 8},
    {"id": "question", "name": "Question", "start_bar": 33, "bars": 4}
  ],
  "track_plan": [
    {
      "id": "piano",
      "name": "Piano Motif",
      "role": "motif",
      "register": {"low": 48, "high": 84},
      "instrument_hint": "acoustic piano",
      "section_jobs": [
        {"section_id": "failure", "intent": "fragmented hesitant motif, sparse and low dynamics", "density": "sparse"},
        {"section_id": "insight", "intent": "motif becomes clearer, gentle inversion", "density": "medium"},
        {"section_id": "build", "intent": "motif ascends and sequences, growing intensity", "density": "dense"},
        {"section_id": "success", "intent": "triumphant but vulnerable statement", "density": "medium"},
        {"section_id": "question", "intent": "motif left hanging on unresolved interval", "density": "sparse"}
      ]
    },
    {
      "id": "strings_high",
      "name": "High Strings",
      "role": "harmony/texture",
      "register": {"low": 62, "high": 96},
      "instrument_hint": "violin section",
      "section_jobs": [
        {"section_id": "failure", "intent": "sustained dissonant cluster, sparse harmonic support", "density": "sparse"},
        {"section_id": "insight", "intent": "soft warm major intervals", "density": "medium"},
        {"section_id": "build", "intent": "rhythmic ostinato and tremolo drive", "density": "dense"},
        {"section_id": "success", "intent": "broad countermelody against motif", "density": "medium"},
        {"section_id": "question", "intent": "single high harmonic fading", "density": "sparse"}
      ]
    },
    {
      "id": "strings_low",
      "name": "Low Strings",
      "role": "harmony/countermelody",
      "register": {"low": 40, "high": 67},
      "instrument_hint": "cello section",
      "section_jobs": [
        {"section_id": "failure", "intent": "dark low pedal tone", "density": "sparse"},
        {"section_id": "insight", "intent": "gentle legato countermelody", "density": "medium"},
        {"section_id": "build", "intent": "pulsing eighth-note harmonic support", "density": "medium"},
        {"section_id": "success", "intent": "supporting legato harmony", "density": "medium"},
        {"section_id": "question", "intent": "sustained unresolved low tone", "density": "sparse"}
      ]
    },
    {
      "id": "bass",
      "name": "Bass Pulse",
      "role": "bass",
      "register": {"low": 28, "high": 48},
      "instrument_hint": "synth bass or double bass",
      "section_jobs": [
        {"section_id": "failure", "intent": "subdued whole-note pulse", "density": "sparse"},
        {"section_id": "insight", "intent": "soft walking quarter notes", "density": "medium"},
        {"section_id": "build", "intent": "driving eighth-note pulse", "density": "dense"},
        {"section_id": "success", "intent": "solid root motion, not overbearing", "density": "medium"},
        {"section_id": "question", "intent": "final low open fifth", "density": "sparse"}
      ]
    },
    {
      "id": "texture",
      "name": "Electronic Texture",
      "role": "texture",
      "register": {"low": 55, "high": 84},
      "instrument_hint": "ambient synth pad",
      "section_jobs": [
        {"section_id": "failure", "intent": "subtle electronic crackle and static", "density": "sparse"},
        {"section_id": "insight", "intent": "shimmering airy pad", "density": "medium"},
        {"section_id": "build", "intent": "arpeggiated synth rhythm increasing density", "density": "dense"},
        {"section_id": "success", "intent": "bright sparkle, supportive", "density": "medium"},
        {"section_id": "question", "intent": "unresolved ambient shimmer fading", "density": "sparse"}
      ]
    },
    {
      "id": "percussion",
      "name": "Light Percussion",
      "role": "percussion",
      "register": {"low": 35, "high": 60},
      "instrument_hint": "brush kit, shaker, rim clicks",
      "section_jobs": [
        {"section_id": "failure", "intent": "soft metronome tick only", "density": "sparse"},
        {"section_id": "insight", "intent": "hi-hat and rim clicks, light", "density": "sparse"},
        {"section_id": "build", "intent": "four-on-floor kick with shaker, light but driving", "density": "dense"},
        {"section_id": "success", "intent": "groove continues, relaxed", "density": "medium"},
        {"section_id": "question", "intent": "single final percussive hit, then silence", "density": "sparse"}
      ]
    }
  ],
  "motif_strategy": "A five-note motif (D-F-A-G-E) is introduced fragmented in failure, clarified in insight through inversion, sequenced and ascended in build, stated triumphantly in success, and left unresolved on a held E natural in question.",
  "harmony_strategy": "Progression moves D minor -> F major -> G major -> C major -> A minor, avoiding V-I cadence. Use mediant and plagal shifts, voice leading by common tones. Final section ends on A minor add9, never resolving to tonic.",
  "groove_strategy": "Sparse eighth-note bass pulse expands to driving sixteenth-note texture in build. Percussion enters lightly, peaks with four-on-floor in build, then reduces to sparse hits in question. Clear edit points at section boundaries."
}

EXPERIMENTAL MUSIC SPEC SCHEMA:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://auto-studio.local/q0/experimental-music-spec.schema.json",
  "title": "ExperimentalMusicSpec",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "tempo_map", "key_map", "sections", "tracks"],
  "properties": {
    "title": {"type": "string", "minLength": 1, "maxLength": 120},
    "tempo_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/tempo_change"}},
    "key_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/key_change"}},
    "sections": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/section"}},
    "tracks": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "#/$defs/track"}}
  },
  "$defs": {
    "time_signature": {
      "type": "object", "additionalProperties": false,
      "required": ["numerator", "denominator"],
      "properties": {
        "numerator": {"type": "integer", "minimum": 1, "maximum": 32},
        "denominator": {"enum": [1, 2, 4, 8, 16, 32]}
      }
    },
    "tempo_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "bpm", "time_signature"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "bpm": {"type": "number", "minimum": 30, "maximum": 300},
        "time_signature": {"$ref": "#/$defs/time_signature"}
      }
    },
    "key_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "tonic", "mode"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "tonic": {"type": "string", "minLength": 1, "maxLength": 8},
        "mode": {"type": "string", "minLength": 1, "maxLength": 32}
      }
    },
    "section": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "label", "start_bar", "length_bars", "intent"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "label": {"type": "string", "minLength": 1, "maxLength": 80},
        "start_bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "length_bars": {"type": "integer", "minimum": 1, "maximum": 128},
        "intent": {"type": "string", "minLength": 1, "maxLength": 240}
      }
    },
    "register": {
      "type": "object", "additionalProperties": false,
      "required": ["low", "high"],
      "properties": {
        "low": {"type": "integer", "minimum": 0, "maximum": 127},
        "high": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "note": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "duration", "pitch", "velocity"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "duration": {"type": "number", "exclusiveMinimum": 0},
        "pitch": {"type": "integer", "minimum": 0, "maximum": 127},
        "velocity": {"type": "integer", "minimum": 1, "maximum": 127}
      }
    },
    "cc": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "controller", "value"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "controller": {"type": "integer", "minimum": 0, "maximum": 127},
        "value": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "region": {
      "type": "object", "additionalProperties": false,
      "required": ["section_id", "notes", "cc"],
      "properties": {
        "section_id": {"type": "string", "minLength": 1, "maxLength": 48},
        "notes": {"type": "array", "maxItems": 2048, "items": {"$ref": "#/$defs/note"}},
        "cc": {"type": "array", "maxItems": 1024, "items": {"$ref": "#/$defs/cc"}}
      }
    },
    "track": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "name", "role", "register", "instrument_hint", "regions"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "name": {"type": "string", "minLength": 1, "maxLength": 80},
        "role": {"type": "string", "minLength": 1, "maxLength": 80},
        "register": {"$ref": "#/$defs/register"},
        "instrument_hint": {"type": "string", "minLength": 1, "maxLength": 120},
        "regions": {"type": "array", "maxItems": 48, "items": {"$ref": "#/$defs/region"}}
      }
    }
  }
}
